const D = { density:.6, energy:.62, speed:1, scale:1, warp:.5, hue:210, x:.5, y:.5, style:'galactic', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const style = P.style;
const cx = width * P.x, cy = height * P.y;
const R = u * 0.46 * (0.6 + P.scale * 0.6);           // galaxy radius (fills frame)
const NB = Math.round(160 + P.density * 320);          // body count 160..480

// persistent trail buffer
if (!S.buf || S.bkey !== width + 'x' + height) {
  S.buf = createGraphics(width, height); S.buf.colorMode(HSB, 360, 100, 100, 100); S.buf.pixelDensity(1);
  S.bkey = width + 'x' + height; S.seeded = false;
}
const g = S.buf;

let sr = ((P.seed + 1) * 2654435761) >>> 0;
function rnd(){ sr ^= sr<<13; sr>>>=0; sr ^= sr>>17; sr ^= sr<<5; sr>>>=0; return sr/4294967295; }
function gauss(){ return (rnd()+rnd()+rnd()-1.5)*0.9; }

// seed a two-arm logarithmic-spiral disk with orbital velocity (differential rotation -> winding arms)
const sec = K.section | 0;
function seed() {
  sr = ((P.seed + 1 + sec*131) * 2654435761) >>> 0;
  const arms = 2 + (Math.round(P.warp*2));            // 2..4 spiral arms
  const wind = 2.6;                                   // spiral tightness
  S.bx = new Float32Array(NB); S.by = new Float32Array(NB);
  S.vx = new Float32Array(NB); S.vy = new Float32Array(NB); S.hu = new Float32Array(NB);
  for (let i = 0; i < NB; i++) {
    const rr = R * Math.pow(rnd(), 0.62);              // denser toward center
    const arm = Math.floor(rnd()*arms);
    const th = wind * Math.log((rr + R*0.06)/(R*0.06)) + arm*(TAU/arms) + gauss()*0.28;
    const px = cx + Math.cos(th)*rr, py = cy + Math.sin(th)*rr*0.98;
    S.bx[i] = px; S.by[i] = py;
    // TRUE circular-orbit speed for the softened central potential (so stars orbit, not plunge)
    const GMseed = u*u * 0.0016 * (0.6 + P.speed);
    const amag = GMseed * rr / Math.pow(rr*rr + (u*0.085)*(u*0.085), 1.5);
    const v = Math.sqrt(amag * rr) * (0.96 + rnd()*0.08);   // tiny eccentricity spread
    const tx = -Math.sin(th), ty = Math.cos(th);
    S.vx[i] = tx*v; S.vy[i] = ty*v;
    S.hu[i] = rr / R;                                  // radius param -> hue/temp
  }
  S.seeded = true; S.seedUsed = P.seed; S.nbUsed = NB; S.secUsed = sec;
  // clear buffer to dark ground on reseed
  g.push(); g.blendMode(BLEND);
  g.drawingContext.fillStyle = 'rgb(4,5,12)'; g.drawingContext.fillRect(0,0,width,height); g.pop();
}
if (!S.seeded || S.seedUsed !== P.seed || S.nbUsed !== NB || S.secUsed !== sec) seed();

const bx=S.bx, by=S.by, vx=S.vx, vy=S.vy, hu=S.hu;
const GM = u*u * 0.0016 * (0.6 + P.speed);             // central mass strength
const soft = (u*0.085)*(u*0.085);                      // softening (no singularity)
const dt = 0.45;
const steps = 3;

// integrate: central gravity + weak differential shear keeps arms alive
for (let st = 0; st < steps; st++) {
  for (let i = 0; i < NB; i++) {
    const dx = cx - bx[i], dy = cy - by[i];
    const r2 = dx*dx + dy*dy + soft;
    const f = GM / (r2 * Math.sqrt(r2));
    vx[i] += dx * f * dt; vy[i] += dy * f * dt;
    bx[i] += vx[i] * dt; by[i] += vy[i] * dt;
  }
}

// ---- render: fade trails, additive glow bodies + core ----
g.push();
g.blendMode(BLEND);
g.noStroke();
g.drawingContext.globalAlpha = 1;
g.fill(230, 40, 6, 26 + (1-P.energy)*8);               // stronger wash -> SHORT trails, stars read as moving points (motion floor)
g.rect(0,0,width,height);

g.blendMode(ADD);
const hb = P.hue;
const spd0 = u*0.004;
for (let i = 0; i < NB; i++) {
  const sp = Math.sqrt(vx[i]*vx[i] + vy[i]*vy[i]);
  const heat = Math.min(1, sp / (spd0*3));             // fast/inner = hot
  let hgt, sat, val, sz;
  if (style === 'plasma')      { hgt = wh(hb + 160 - heat*160); sat = 85; }
  else if (style === 'firefly'){ hgt = wh(40 + heat*20); sat = 78; }
  else if (style === 'heat')   { hgt = wh(60 - heat*60); sat = 90; }
  else if (style === 'mono')   { hgt = 210; sat = 6; }
  else                         { hgt = wh(hb + 40 - heat*70 + hu[i]*30); sat = 55 + heat*30; } // galactic blue->amber
  val = 72 + heat*28;
  sz = (1.1 + (1-hu[i])*2.8) * (u*0.0030) * (0.8 + P.energy*0.8);
  g.fill(hgt, sat, val, 46 + P.energy*32);
  g.circle(bx[i], by[i], sz);
}
// bright galactic core glow
const cg = g.drawingContext.createRadialGradient(cx,cy,1, cx,cy, u*0.22);
cg.addColorStop(0, 'rgba(255,244,220,0.55)');
cg.addColorStop(0.4, 'rgba(255,200,140,0.16)');
cg.addColorStop(1, 'rgba(60,40,120,0)');
g.drawingContext.fillStyle = cg; g.drawingContext.fillRect(0,0,width,height);
g.pop();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
